    /// the <c>textDocument.completion.insertTextMode</c> client capability.
    /// </summary>
    [JsonPropertyName("insertTextMode")]
    public InsertTextMode? InsertTextMode { get; init; }

    /// <summary>
    /// An {@link TextEdit edit} which is applied to a document when selecting
    /// this completion. When an edit is provided the value of
    /// {@link CompletionItem.insertText insertText} is ignored.
    /// </summary>
    [JsonPropertyName("textEdit")]
    public OneOf<TextEdit, InsertReplaceEdit>? TextEdit { get; init; }

